import React, { useState, useEffect, useContext } from 'react';
import { toast } from 'react-toastify';
import api from '../services/api';
import { AuthContext } from '../context/AuthContext';
import { Link } from 'react-router-dom';

const Profile = () => {
  const { user } = useContext(AuthContext);
  const [interests, setInterests] = useState([]);
  const [meetings, setMeetings] = useState([]);

  useEffect(() => {
    const fetchInterests = async () => {
      try {
        const response = await api.get('/properties/interests', {
          headers: { Authorization: `Bearer ${user.token}` },
        });
        setInterests(response.data);
      } catch (error) {
        toast.error('Failed to fetch interests');
      }
    };

    const fetchMeetings = async () => {
      try {
        const response = await api.get('/messages/meetings', {
          headers: { Authorization: `Bearer ${user.token}` },
        });
        setMeetings(response.data);
      } catch (error) {
        toast.error('Failed to fetch meetings');
      }
    };

    fetchInterests();
    fetchMeetings();
  }, [user]);

  return (
    <div className="container mx-auto p-4">
      <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-4">Profile</h2>
      <p className="mb-4">Email: {user.email}</p>
      <h3 className="text-xl font-semibold mb-2">My Interests</h3>
      {interests.length === 0 ? (
        <p className="text-gray-600 dark:text-gray-400">No interests yet.</p>
      ) : (
        <ul className="list-disc pl-5 mb-4">
          {interests.map((property) => (
            <li key={property.id}>{property.title} - {property.city}</li>
          ))}
        </ul>
      )}
      <h3 className="text-xl font-semibold mb-2">My Meetings</h3>
      {meetings.length === 0 ? (
        <p className="text-gray-600 dark:text-gray-400">No meetings scheduled.</p>
      ) : (
        <ul className="list-disc pl-5 mb-4">
          {meetings.map((meeting) => (
            <li key={meeting.id}>
              {meeting.title} - {new Date(meeting.date).toLocaleString()} - {meeting.notes}
            </li>
          ))}
        </ul>
      )}
      <Link
        to="/dashboard"
        className="bg-blue-500 text-white p-2 rounded hover:bg-blue-600"
      >
        Add Property
      </Link>
    </div>
  );
};

export default Profile;
